import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * What the customer list is narrowed down to.
 *
 * <p>Both parts are optional and a customer has to satisfy both: every term of
 * the name search must appear in the customer's first or last name, and the
 * status must be one of the selected ones. {@link #EMPTY} matches everybody.
 *
 * @param name     free text, split into terms on whitespace
 * @param statuses the statuses to show, or empty for all of them
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                // An EnumSet iterates in declaration order, which is the order
                // the statuses are written to the URL in.
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /**
     * The name search as the terms a customer has to match, all of them, each
     * already folded for comparison.
     */
    public List<String> nameTerms() {
        return WHITESPACE.splitAsStream(name.strip())
                .filter(term -> !term.isEmpty())
                .map(CustomerFilter::fold)
                .toList();
    }

    /** Whether this filter narrows anything down at all. */
    public boolean isEmpty() {
        return statuses.isEmpty() && nameTerms().isEmpty();
    }

    /**
     * Folds text down to what name matching compares: lower case, with accents
     * removed, so that {@code makinen}, {@code MAKINEN} and {@code mäkinen} all
     * match {@code Mäkinen}. Both sides of a comparison have to be folded.
     */
    public static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
