+    }
+
+    @Test
+    void whitespaceAroundAndBetweenTermsIsNotSignificant() {
+        filterByName("ada aal");
+        int expected = test(grid()).size();
+
+        filterByName("   ada    aal  ");
+        assertEquals(expected, test(grid()).size());
+
+        filterByName("   ");
+        assertEquals(500, test(grid()).size());
+    }
+
+    @Test
+    void nameMatchingIgnoresCaseAndAccents() {
+        filterByName("Mäkinen");
+        int accented = test(grid()).size();
+        assertTrue(accented > 0, "The data set must contain a Mäkinen");
+
+        filterByName("makinen");
+        assertEquals(accented, test(grid()).size());
+
+        filterByName("MAKINEN");
+        assertEquals(accented, test(grid()).size());
+
+        filterByName("josephine");
+        assertTrue(test(grid()).size() > 0, "'josephine' must match Joséphine");
+    }
+
+    @Test
+    void statusFilterShowsOnlySelectedStatuses() {
+        filterByStatus(CustomerStatus.ACTIVE);
+
+        Grid<?> grid = grid();
+        int active = test(grid).size();
+        assertTrue(active > 0 && active < 500);
+        assertEquals("Showing " + active + " of 500", summaryText());
+        assertEquals("ACTIVE", test(grid).getCellText(0, 4));
+
+        filterByStatus(CustomerStatus.ACTIVE, CustomerStatus.CLOSED);
+        assertTrue(test(grid()).size() > active);
+
+        filterByStatus();
+        assertEquals(500, test(grid()).size());
+    }
+
+    @Test
+    void bothFiltersHaveToMatch() {
+        filterByName("virtanen");
+        int byName = test(grid()).size();
+
+        filterByStatus(CustomerStatus.CLOSED);
+        int byBoth = test(grid()).size();
+        assertTrue(byBoth < byName, "Adding a status must narrow the list further");
+
+        Grid<?> grid = grid();
+        for (int row = 0; row < byBoth; row++) {
+            assertEquals("Virtanen", test(grid).getCellText(row, 1));
+            assertEquals("CLOSED", test(grid).getCellText(row, 4));
+        }
+    }
+
+    /** A filtered grid is still lazily loaded: the backend does the filtering. */
+    @Test
+    void filteringHappensInTheBackend() {
+        filterByStatus(CustomerStatus.ACTIVE);
+        queryLog.clear();
+        test(grid()).getCellText(0, 0);
+
+        assertFalse(queryLog.pageQueries().isEmpty(),
+                "The grid must fetch its rows from the backend");
+        queryLog.pageQueries().forEach(page -> assertTrue(
+                page.limit() <= CustomerRepository.MAX_PAGE_SIZE,
+                "A page query asked for " + page.limit() + " rows, more than the backend serves"));
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "A filtered grid pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    /** The summary follows the filter on its own, without the grid being read. */
+    @Test
+    void theSummaryFollowsTheFilter() {
+        filterByName("virtanen");
+        assertTrue(summaryText().matches("Showing \\d+ of 500"), summaryText());
+        assertNotEquals("Showing 500 of 500", summaryText());
+
+        filterByName("");
+        assertEquals("Showing 500 of 500", summaryText());
+    }
+
+    /** The summary reports the count the backend served, not the rows on screen. */
+    @Test
+    void summaryReportsTheBackendCount() {
+        queryLog.clear();
+        filterByName("virtanen");
+        int matching = test(grid()).size();
+
+        assertTrue(queryLog.countQueries().contains(matching),
+                "The count in the summary must come from a count query, "
+                        + "the log holds " + queryLog.countQueries());
+        assertEquals("Showing " + matching + " of 500", summaryText());
+    }
+
+    @Test
+    void sortingKeepsWorkingWhileFiltered() {
+        filterByStatus(CustomerStatus.ACTIVE);
+        Grid<?> grid = grid();
+
+        test(grid).sortByColumn("lastName", SortDirection.ASCENDING);
+        String first = test(grid).getCellText(0, 1);
+        test(grid).sortByColumn("lastName", SortDirection.DESCENDING);
+        String last = test(grid).getCellText(0, 1);
+
+        assertTrue(first.compareToIgnoreCase(last) < 0,
+                "Sorting a filtered grid must reorder it, got " + first + " and " + last);
+        assertEquals("ACTIVE", test(grid).getCellText(0, 4));
+        queryLog.pageQueries().forEach(page -> assertTrue(
+                page.limit() <= CustomerRepository.MAX_PAGE_SIZE,
+                "A page query asked for " + page.limit() + " rows"));
+    }
+
+    @Test
+    void urlParametersApplyTheFilterAndShowItInTheFields() {
+        navigateWithQuery("name=vir&status=ACTIVE,CLOSED");
+
+        assertEquals("vir", nameField().getValue());
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), statusField().getValue());
+
+        Grid<?> grid = grid();
+        int matching = test(grid).size();
+        assertTrue(matching > 0 && matching < 500);
+        assertEquals("Showing " + matching + " of 500", summaryText());
+        for (int row = 0; row < Math.min(matching, 10); row++) {
+            assertTrue(test(grid).getCellText(row, 1).toLowerCase().contains("vir"));
+            assertTrue(List.of("ACTIVE", "CLOSED").contains(test(grid).getCellText(row, 4)));
+        }
+    }
+
+    @Test
+    void anUnknownStatusInTheUrlIsIgnored() {
+        navigateWithQuery("status=ACTIVE,NONSENSE");
+
+        assertEquals(Set.of(CustomerStatus.ACTIVE), statusField().getValue());
+    }
+
+    /** Opens the view the way a bookmarked, filtered URL does. */
+    private void navigateWithQuery(String queryString) {
+        UI.getCurrent().navigate(CustomerListView.class, QueryParameters.fromString(queryString));
+    }
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    private TextField nameField() {
+        return find(TextField.class).single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private MultiSelectComboBox<CustomerStatus> statusField() {
+        return find(MultiSelectComboBox.class).single();
+    }
+
+    private String summaryText() {
+        return find(Span.class).single().getText();
+    }
+
+    private void filterByName(String name) {
+        test(nameField()).setValue(name);
+    }
+
+    private void filterByStatus(CustomerStatus... statuses) {
+        if (statuses.length == 0) {
+            statusField().clear();
+        } else {
+            test(statusField()).selectItem(
+                    Stream.of(statuses).map(CustomerStatus::name).toArray(String[]::new));
+        }
+    }
 }
